<section class="card"><div class="toolbar"><div><h2>Datos de contacto y redes sociales</h2><p class="muted">Puedes agregar, editar, ocultar, ordenar o eliminar cada elemento.</p></div><button class="btn" type="button" id="add-topbar-item"><i class="bi bi-plus-circle"></i> Agregar elemento</button></div><p class="muted">Arrastra las filas desde el icono de puntos para cambiar su orden. También puedes usar las flechas del teclado.</p><div class="table-wrap"><table id="topbar-sort-table"><thead><tr><th>Orden</th><th>Tipo</th><th>Nombre</th><th>Valor / enlace</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="topbar-sort-body"><?php foreach($items as $i):?><tr draggable="true" data-item-id="<?=(int)$i['id_item']?>"><td><button type="button" class="drag-handle" draggable="true" aria-label="Arrastrar para ordenar <?=te($i['titulo'])?>" title="Arrastrar para ordenar; flechas arriba y abajo con teclado"><i class="bi bi-grip-vertical"></i></button><span class="sort-position"><?=(int)$i['orden']?></span></td><td><?=te($types[$i['etiqueta']??'']??'Otro')?></td><td><strong><?=te($i['titulo'])?></strong></td><td><?=te(mb_strimwidth((string)$i['url'],0,48,'…'))?></td><td><span class="pill <?=($i['visible']??'si')==='si'?'':'off'?>"><?=($i['visible']??'si')==='si'?'Visible':'Oculto'?></span></td><td><div class="actions"><a href="?item=<?=(int)$i['id_item']?>" title="Editar" aria-label="Editar <?=te($i['titulo'])?>"><i class="bi bi-pencil-square"></i></a><form method="post"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="toggle"><input type="hidden" name="id_item" value="<?=(int)$i['id_item']?>"><button title="Cambiar visibilidad" aria-label="Cambiar visibilidad"><i class="bi bi-eye<?=($i['visible']??'si')==='si'?'':'-slash'?>"></i></button></form><form method="post" onsubmit="return confirm('¿Eliminar este elemento de la barra superior?')"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="delete"><input type="hidden" name="id_item" value="<?=(int)$i['id_item']?>"><button title="Eliminar" aria-label="Eliminar"><i class="bi bi-trash"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="6" class="muted">Todavía no hay elementos. Agrega una dirección, teléfono, correo o red social.</td></tr><?php endif;?></tbody></table></div><form id="topbar-reorder-form" method="post" hidden><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="reorder"><input type="hidden" name="ordered_ids" id="ordered-ids"></form></section>
<dialog class="editor-dialog patrona-modal-panel" id="form-elemento" aria-labelledby="editor-dialog-title"><form method="post"><div class="editor-dialog-header patrona-modal-header"><h2 id="editor-dialog-title"><?=$edit?'Editar elemento':'Agregar elemento'?></h2><button type="button" class="dialog-close patrona-modal-close" id="close-editor-dialog" aria-label="Cerrar"><span aria-hidden="true">×</span></button></div><div class="editor-dialog-body patrona-modal-body"><input type="hidden" name="csrf" value="<?=te($_SESSION['patrona_csrf'])?>"><input type="hidden" name="accion" value="save"><input type="hidden" name="id_item" value="<?=(int)($edit['id_item']??0)?>"><div class="grid"><label class="field">Tipo de elemento<span class="type-picker"><span class="type-logo" id="type-logo" aria-hidden="true"><i class="bi bi-geo-alt"></i></span><select name="tipo" id="tipo" required><?php foreach($types as $key=>$label):?><option value="<?=te($key)?>" <?=($edit['etiqueta']??'')===$key?'selected':''?>><?=te($label)?></option><?php endforeach;?></select></span></label><label class="field">Nombre visible<input name="titulo" maxlength="120" required placeholder="Ej.: Instagram, Secretaría, Dirección" value="<?=te($edit['titulo']??'')?>"></label><label class="field">Dirección, teléfono, correo o URL<input name="url" maxlength="500" id="valor" placeholder="https://... o contacto@colegio.cl" value="<?=te($edit['url']??'')?>"></label><div class="field visibility-field"><span>Visibilidad</span><label class="visibility-switch"><input type="checkbox" id="item-visible-check" <?=($edit['visible']??'si')==='si'?'checked':''?>><span class="visibility-track" aria-hidden="true"></span><span id="visibility-label">Visible en el sitio</span></label><input type="hidden" name="visible" id="item-visible-value" value="<?=te($edit['visible']??'si')?>"></div></div><p class="muted">Para redes sociales y enlaces, utiliza una URL completa con https://. Para dirección, escribe la ubicación; para teléfono, el número; para correo, la dirección electrónica.</p></div><div class="editor-dialog-footer patrona-modal-footer"><button class="btn" type="submit"><i class="bi bi-check2-circle"></i> Guardar elemento</button></div></form></dialog>
<?php endif;?></div></main></div></div><script>
(()=>{'use strict';
const dialog=document.getElementById('form-elemento'),add=document.getElementById('add-topbar-item');
if(!dialog)return;
const form=dialog.querySelector('form'),type=form.elements.namedItem('tipo'),visible=document.getElementById('item-visible-check'),visibleValue=document.getElementById('item-visible-value'),visibleLabel=document.getElementById('visibility-label'),logo=document.getElementById('type-logo');
const icons={direccion:'geo-alt-fill',telefono:'telephone-fill',correo:'envelope-fill',enlace:'box-arrow-up-right',instagram:'instagram',facebook:'facebook',youtube:'youtube',linkedin:'linkedin',x:'twitter-x'};
function updateIcon(){const icon=icons[type.value]||'link-45deg';logo.innerHTML='<i class="bi bi-'+icon+'"></i>';logo.title=type.options[type.selectedIndex]?.text||'';}
function updateVisibility(){visibleValue.value=visible.checked?'si':'no';visibleLabel.textContent=visible.checked?'Visible en el sitio':'Oculto en el sitio';form.querySelectorAll('.item-edit-field').forEach(el=>el.classList.toggle('dialog-muted-fields',!visible.checked));}
type.addEventListener('change',updateIcon);visible.addEventListener('change',updateVisibility);
form.querySelectorAll('.field').forEach(el=>{if(!el.classList.contains('visibility-field'))el.classList.add('item-edit-field');});
updateIcon();updateVisibility();
const close=()=>{dialog.close();if(new URLSearchParams(location.search).has('item'))location.replace('editar_topbar.php');};
document.getElementById('close-editor-dialog')?.addEventListener('click',close);
dialog.addEventListener('cancel', e => e.preventDefault());
add?.addEventListener('click',()=>{form.reset();form.elements.namedItem('id_item').value='0';document.getElementById('editor-dialog-title').textContent='Agregar elemento';updateIcon();updateVisibility();dialog.showModal();});
if(new URLSearchParams(location.search).has('item'))dialog.showModal();
const body=document.getElementById('topbar-sort-body'),orderForm=document.getElementById('topbar-reorder-form');
if(body&&orderForm){
 let dragged=null,initialOrder=Array.from(body.querySelectorAll('tr[data-item-id]')).map(tr=>tr.dataset.itemId).join(',');
 const rows=()=>Array.from(body.querySelectorAll('tr[data-item-id]'));
 function renumber(){rows().forEach((tr,i)=>{const n=tr.querySelector('.sort-position');if(n)n.textContent=String(i+1);});}
 function save(){const ids=rows().map(tr=>tr.dataset.itemId).join(',');if(ids!==initialOrder){document.getElementById('ordered-ids').value=ids;orderForm.submit();}}
 body.addEventListener('dragstart',e=>{const handle=e.target.closest('.drag-handle');if(!handle){e.preventDefault();return;}dragged=handle.closest('tr[data-item-id]');dragged.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged.dataset.itemId);});
 body.addEventListener('dragover',e=>{if(!dragged)return;const target=e.target.closest('tr[data-item-id]');if(!target||target===dragged)return;e.preventDefault();const rect=target.getBoundingClientRect();body.insertBefore(dragged,e.clientY<rect.top+rect.height/2?target:target.nextSibling);renumber();});
 body.addEventListener('drop',e=>{if(!dragged)return;e.preventDefault();dragged.classList.remove('dragging');dragged=null;save();});
 body.addEventListener('dragend',()=>{if(dragged){dragged.classList.remove('dragging');dragged=null;renumber();save();}});
 body.addEventListener('keydown',e=>{if(!e.target.closest('.drag-handle')||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const tr=e.target.closest('tr'),other=e.key==='ArrowUp'?tr.previousElementSibling:tr.nextElementSibling;if(!other||!other.matches('tr[data-item-id]'))return;if(e.key==='ArrowUp')body.insertBefore(tr,other);else body.insertBefore(other,tr);renumber();e.target.focus();save();});
}
})();
</script></body></html>
